import java.util.*;

class Solution {
    public ListNode reverseBetween(ListNode head, int lo, int hi) {
        ListNode dummy = new ListNode(0, head), before = dummy;
        for (int i = 1; i < lo; i++) before = before.next;   // node at position lo-1
        ListNode start = before.next;                        // becomes the stretch's tail
        for (int i = 0; i < hi - lo; i++) {
            ListNode move = start.next;    // next node to pull to the front
            start.next = move.next;
            move.next = before.next;
            before.next = move;
        }
        return dummy.next;
    }
}

