class Solution:
    def reverseBetween(self, head: Optional[ListNode], lo: int, hi: int) -> Optional[ListNode]:
        d = ListNode(0, head); p = d
        for _ in range(lo - 1): p = p.next
        c = p.next
        for _ in range(hi - lo):
            n = c.next; c.next = n.next; n.next = p.next; p.next = n
        return d.next
